-- STATUS: LIVE angewandt am 2026-08-04. Version v1.142.
--
-- Vorlagen, Belohnungen und Erfolgsgeschichten sind EIN geteilter Satz, den
-- alle Berater zeigen. Am 23.07.2026 kam beim Anlegen des Beraters
-- "Max Kudlek" (7b176742-…, ist_aktiv = false) ein kompletter zweiter Satz in
-- die Tabellen. Weil die Lese-Policies alle Zeilen öffentlich freigeben, stand
-- danach jede Belohnung, jede Themenwelt und jede Erfolgsgeschichte doppelt:
-- in der Präsentation, im Empfehlungs-Formular, im Promoter-Bereich, in den
-- Admin-Editoren und auf der Empfänger-Seite.
--
-- Der Client filtert Dubletten seit v1.142 zusätzlich weg (eineZeileProSchluessel
-- in js/supabase.js). Dieses Skript beseitigt die Ursache.
--
-- Geprüft vor dem Löschen:
--   * kein Fremdschlüssel zeigt auf belohnungs_stufen
--   * Max Kudlek hat 0 Promoter, 0 Empfehlungen, 0 Prämien
--   * alle Zeilen sind inhaltsgleiche Kopien der Zeilen von Kai Blobel
-- ============================================================================

delete from public.belohnungs_stufen  where berater_id = '7b176742-7b1a-4555-ba90-c5f6041fe4e1';  -- 7 Zeilen
delete from public.vorlagen           where berater_id = '7b176742-7b1a-4555-ba90-c5f6041fe4e1';  -- 8 Zeilen
delete from public.erfolgsgeschichten where berater_id = '7b176742-7b1a-4555-ba90-c5f6041fe4e1';  -- 3 Zeilen

-- Erwartet danach: belohnungs_stufen 7, vorlagen 8, erfolgsgeschichten 3
-- select count(*) from public.belohnungs_stufen;

-- ============================================================================
-- ROLLBACK — falls Max Kudlek doch wieder aktiv wird, diesen Block ausführen.
-- Stand der Zeilen zum Zeitpunkt des Löschens (2026-08-04).
